function pveArtifactTurnEffects(data) {
    let extraHunger=0, extraThirst=0, leak=0, radiationResist=0;
    for(const name of (Array.isArray(data.artifactSlots)?data.artifactSlots:[])){
        if(!name) continue;
        const st=pveArtifactStatsForName(name);
        if(Number(st.hunger)<0) extraHunger+=-Number(st.hunger);
        if(Number(st.thirst)<0) extraThirst+=-Number(st.thirst);
        if(Number(st.radiationLeak)<0) leak+=-Number(st.radiationLeak);
        if(Number(st.radiation)>0) radiationResist+=Number(st.radiation);
    }
    data.hunger=Math.max(0,(Number(data.hunger)||0)-extraHunger);
    data.thirst=Math.max(0,(Number(data.thirst)||0)-extraThirst);
    const netLeak=Math.max(0,leak-radiationResist);
    if(netLeak>0){
        data.radiation=Math.min(100,(Number(data.radiation)||0)+netLeak);
        data.health=Math.round(Math.max(0,(Number(data.health)||0)-netLeak)*10)/10;
        if(data.radiation>=100) data.health=0;
    }
    return {extraHunger,extraThirst,netLeak};
}

function pveRadiationDamage(data) {
    const rad=Math.max(0,Number(data.radiation)||0);
    if(rad<=0) return 0;
    data.health=Math.round(Math.max(0,(Number(data.health)||0)-rad)*10)/10;
    return rad;
}

app.post('/api/raid/step',requireAuth,rateLimit('raid-step',20,10000),(req,res)=>{
    const playerId=String(req.telegramUser.id),token=String(req.body?.raidToken||'');
    try{
        const tx=db.transaction(()=>{
            const sess=raidSession(playerId,token);if(!sess)return{success:false,error:'Рейд не найден'};
            if(sess.pending_type)return{success:false,error:'Сначала завершите текущую встречу'};
            const row=db.prepare('SELECT data FROM players WHERE id=?').get(playerId);if(!row)return{success:false,error:'Игрок не найден'};
            const data=safeParsePlayerData(row.data);
            data.hunger=Math.max(0,Math.min(Number(data.maxHunger)||100,(Number(data.hunger)||0)-5));
            data.thirst=Math.max(0,Math.min(Number(data.maxThirst)||100,(Number(data.thirst)||0)-5));
            const turnEffects=pveArtifactTurnEffects(data);
            const radiationDamage=pveRadiationDamage(data);
            let starvationDamage=0;
            if(data.hunger<=0)starvationDamage+=3;if(data.thirst<=0)starvationDamage+=3;
            if(starvationDamage>0)data.health=Math.round(((Number(data.health)||0)-starvationDamage)*10)/10;
            if(data.health<=0){
                pveApplyDeathNow(data);
                db.prepare('DELETE FROM raid_sessions WHERE player_id=?').run(playerId);
                db.prepare('DELETE FROM pve_battles WHERE player_id=?').run(playerId);
                db.prepare('UPDATE players SET data=?,last_seen=? WHERE id=?').run(JSON.stringify(data),Date.now(),playerId);
                return{success:true,died:true,state:raidState(data),turnEffects,radiationDamage,starvationDamage};
            }
            let event={type:'none'},pendingType=null,pendingPayload=null;
            const roll=Math.random();
            if(roll<0.30){
                const npc=raidCreateNpcPayload(data);
                if(raidIsFactionHostile(playerId,data,npc.faction)){
                    const battleToken=crypto.randomBytes(24).toString('hex');
                    db.prepare('DELETE FROM pve_battles WHERE player_id=?').run(playerId);
                    db.prepare('INSERT INTO pve_battles(player_id,token,enemy_kind,enemy_key,payload,started_at) VALUES(?,?,?,?,?,?)')
                      .run(playerId,battleToken,'npc',`${npc.faction}:${npc.tier}:${npc.name}`,JSON.stringify(npc),Date.now());
                    pendingType='battle';pendingPayload=JSON.stringify({battleToken});
                    event={type:'battle',enemy:{...npc,battleToken,faction:{name:npc.faction}}};
                }else{
                    pendingType='friendly';pendingPayload=JSON.stringify(npc);
                    event={type:'friendly',npc:{...npc,faction:{name:npc.faction}}};
                }
            }else if(roll<0.60){
                const encounterTier=raidEncounterTier(data);
                const hasT9=data.detector&&data.detector.name==='ВИЗИРЬ';
                const pool=RAID_ANOMALIES.filter(a=>Number(a.tier)<=encounterTier&&(!a.isNamedArtifactAnomaly||hasT9));
                const a=pool[Math.floor(Math.random()*pool.length)];
                const payload={...a,attemptsUsed:0,resolved:false};
                pendingType='anomaly';pendingPayload=JSON.stringify(payload);event={type:'anomaly',anomaly:payload};
            }else if(roll<0.80){
                const mutant=raidCreateMutantPayload(data);
                if(mutant){
                    const battleToken=crypto.randomBytes(24).toString('hex');
                    db.prepare('DELETE FROM pve_battles WHERE player_id=?').run(playerId);
                    db.prepare('INSERT INTO pve_battles(player_id,token,enemy_kind,enemy_key,payload,started_at) VALUES(?,?,?,?,?,?)')
                      .run(playerId,battleToken,'mutant',mutant.name,JSON.stringify(mutant),Date.now());
                    pendingType='battle';pendingPayload=JSON.stringify({battleToken});
                    event={type:'battle',enemy:{...mutant,battleToken}};
                }
            }else if(roll<0.82){
                const reward=raidCreateLuckyReward(data);
                pendingType='lucky';pendingPayload=JSON.stringify(reward);event={type:'lucky',text:reward.text};
            }
            db.prepare('UPDATE raid_sessions SET pending_type=?,pending_payload=?,updated_at=? WHERE player_id=? AND token=?')
              .run(pendingType,pendingPayload,Date.now(),playerId,token);
            db.prepare('UPDATE players SET data=?,last_seen=? WHERE id=?').run(JSON.stringify(data),Date.now(),playerId);
            return{success:true,died:false,state:raidState(data),event,turnEffects,radiationDamage,starvationDamage};
        });
        return res.json(tx());
    }catch(e){console.error('[/api/raid/step]',e);return res.status(500).json({success:false,error:'Ошибка шага рейда'});}
});

app.post('/api/raid/anomaly/search',requireAuth,rateLimit('raid-anomaly-search',10,10000),(req,res)=>{
    const playerId=String(req.telegramUser.id),token=String(req.body?.raidToken||'');
    try{
        const tx=db.transaction(()=>{
            const sess=raidSession(playerId,token);if(!sess||sess.pending_type!=='anomaly')return{success:false,error:'Аномалия уже недоступна'};
            const a=JSON.parse(sess.pending_payload||'{}');if(a.resolved)return{success:false,error:'Поиск уже завершён'};
            const row=db.prepare('SELECT data FROM players WHERE id=?').get(playerId);if(!row)return{success:false,error:'Игрок не найден'};
            const data=safeParsePlayerData(row.data);data.inventory=data.inventory||{};data.stats=data.stats||{};
            a.attemptsUsed=(Number(a.attemptsUsed)||0)+1;
            const maxAttempts=a.isNamedArtifactAnomaly?1:3;if(a.attemptsUsed>maxAttempts)return{success:false,error:'Попытки исчерпаны'};
            let chance;
            const effLuck=(Number(data.luck)||0)+(pveIsEquippedArmor(data,'Броня Зоны')?20:0);
            if(a.isNamedArtifactAnomaly)chance=5;
            else{
                const ranges={1:[5,10],2:[10,20],3:[20,30]},r=ranges[a.attemptsUsed]||[20,30];
                chance=r[0]+Math.random()*(r[1]-r[0])+effLuck*0.1+(Number(data.detector&&data.detector.tier)||0);
                if(data.detector&&data.detector.name==='ВИЗИРЬ')chance+=10;
                if(Number(a.tier)===8)chance+=5;
                chance+=pveFactionBonuses(playerId,data,null).artifactFindChancePct;
            }
            const rawRad=86+Math.floor(Math.random()*8),radRes=Math.max(0,Number(data.radiationResist)||0);
            const radiationAdded=Math.max(0,rawRad-radRes);
            data.radiation=Math.min(100,(Number(data.radiation)||0)+radiationAdded);
            const specific=Number(data.anomalyResist&&data.anomalyResist[a.name])||0;
            const searchDmg=Math.max(0,radiationAdded-effLuck*0.5-Math.max(0,specific));
            data.health=Math.round(Math.max(0,(Number(data.health)||0)-searchDmg)*10)/10;
            if(data.radiation>=100)data.health=0;
            const anomalyDmg=Math.max(0,Number(a.tier)*4-specific);
            if(anomalyDmg>0)data.health=Math.round(Math.max(0,data.health-anomalyDmg)*10)/10;
            const turnEffects=pveArtifactTurnEffects(data);
            if(data.radiation>=100)data.health=0;
            let found=[],success=Math.random()*100<chance;
            if(success){
                if(a.isNamedArtifactAnomaly){
                    const named=db.prepare('SELECT * FROM named_artifacts WHERE anomaly_index=? AND claimed_by IS NULL ORDER BY RANDOM() LIMIT 1').get(Number(a.anomalyIndex)||0);
                    if(named){
                        const claim=db.prepare('UPDATE named_artifacts SET claimed_by=?,claimed_at=? WHERE id=? AND claimed_by IS NULL').run(playerId,Date.now(),named.id);
                        if(claim.changes===1){pveAddItem(data,named.artifact_name,1,true);found.push(named.artifact_name);}
                    }
                }else if(Array.isArray(a.artifacts)&&a.artifacts.length){
                    const name=questBalance.pickArtifact(a.artifacts)||a.artifacts[0];pveAddItem(data,name,1,true);found.push(name);
                    if(pveIsEquippedArmor(data,'Броня Зоны')&&Math.random()<0.5){
                        const second=questBalance.pickArtifact(a.artifacts)||a.artifacts[0];pveAddItem(data,second,1,true);found.push(second);
                    }
                }
            }
            if(found.length){
                data.luck=Math.min(100,(Number(data.luck)||0)+0.1);
                data.stats.artifactsFound=(Number(data.stats.artifactsFound)||0)+found.length;
                data.stats.artifactsByTier=data.stats.artifactsByTier||{};
                data.stats.artifactsByTier[a.tier]=(Number(data.stats.artifactsByTier[a.tier])||0)+found.length;
                a.resolved=true;
            }else if(a.attemptsUsed>=maxAttempts)a.resolved=true;
            if(data.health<=0){
                pveApplyDeathNow(data);db.prepare('DELETE FROM raid_sessions WHERE player_id=?').run(playerId);
                db.prepare('DELETE FROM pve_battles WHERE player_id=?').run(playerId);
                db.prepare('UPDATE players SET data=?,last_seen=? WHERE id=?').run(JSON.stringify(data),Date.now(),playerId);
                return{success:true,died:true,state:raidState(data),found,attempt:a.attemptsUsed,resolved:true,radiationAdded,searchDmg,anomalyDmg,turnEffects,chance};
            }
            db.prepare('UPDATE raid_sessions SET pending_payload=?,updated_at=? WHERE player_id=? AND token=?').run(JSON.stringify(a),Date.now(),playerId,token);
            db.prepare('UPDATE players SET data=?,last_seen=? WHERE id=?').run(JSON.stringify(data),Date.now(),playerId);
            return{success:true,died:false,state:raidState(data),found,attempt:a.attemptsUsed,resolved:a.resolved,radiationAdded,searchDmg,anomalyDmg,turnEffects,chance};
        });
        return res.json(tx());
    }catch(e){console.error('[/api/raid/anomaly/search]',e);return res.status(500).json({success:false,error:'Ошибка поиска в аномалии'});}
});

app.post('/api/raid/anomaly/finish',requireAuth,(req,res)=>{
    const playerId=String(req.telegramUser.id),token=String(req.body?.raidToken||'');
    const sess=raidSession(playerId,token);if(!sess||sess.pending_type!=='anomaly')return res.json({success:false,error:'Аномалия не найдена'});
    const a=JSON.parse(sess.pending_payload||'{}');if(!a.resolved)return res.json({success:false,error:'Поиск ещё не завершён'});
    raidClearPending(playerId);return res.json({success:true});
});

