function pveArtifactStatsForName(name) {
    if(!name) return {};
    const exact=String(name);
    const crafted=db.prepare('SELECT stats FROM crafted_artifacts WHERE name=?').get(exact);
    if(crafted){
        try{
            const st=JSON.parse(crafted.stats||'{}');
            return st && typeof st==='object' ? st : {};
        }catch(_){ return {}; }
    }
    const clean=String(exact).replace(/[\u200B\u200C]+$/,'');
    const base=SHOP_ARTIFACTS.find(a=>a.name===clean);
    return base && base.stats && typeof base.stats==='object' ? base.stats : {};
}

function pveApplyDeathNow(data) {
    data.inventory=data.inventory||{};
    data.stats=data.stats||{};
    const kept={};
    for(const [name,qty] of Object.entries(data.inventory)){
        const base=pveBaseName(name);
        const art=SHOP_ARTIFACTS.find(a=>a.name===base);
        const named=db.prepare('SELECT 1 FROM named_artifacts WHERE artifact_name=? LIMIT 1').get(base);
        if((art && art.isNamedArtifact) || named) kept[name]=qty;
    }
    data.inventory=kept;
    data.quickSlots=[null,null,null,null];
    data.stats.deaths=(Number(data.stats.deaths)||0)+1;
    data.health=Number(data.maxHealth)||100;
    data.hunger=Number(data.maxHunger)||100;
    data.thirst=Number(data.maxThirst)||100;
    data.radiation=0;
}

function pveApplyConsumableServer(data,item) {
    if(!item) return;
    const maxHealth=Math.max(1,Number(data.maxHealth)||100);
    const maxHunger=Math.max(1,Number(data.maxHunger)||100);
    const maxThirst=Math.max(1,Number(data.maxThirst)||100);
    if(item.type==='food') data.hunger=Math.min(maxHunger,(Number(data.hunger)||0)+(Number(item.restore)||0));
    if(item.type==='water') data.thirst=Math.min(maxThirst,(Number(data.thirst)||0)+(Number(item.restore)||0));
    if(item.type==='medkit'){
        data.health=Math.min(maxHealth,(Number(data.health)||0)+(Number(item.restore)||0));
        const prev=Math.max(0,Number(data.vitality)||0);
        data.vitality=Math.min(100,prev+0.1);
        data.maxHealth=(Number(data.maxHealth)||100)+(data.vitality-prev);
        data.health=Math.min(Number(data.maxHealth)||100,data.health);
    }
    if(item.type==='antirad'){
        data.hunger=Math.max(0,(Number(data.hunger)||0)-(Number(item.foodCost)||0));
        data.thirst=Math.max(0,(Number(data.thirst)||0)-(Number(item.waterCost)||0));
    }
    if(Number(item.radiationRemove)>0){
        data.radiation=Math.max(0,(Number(data.radiation)||0)-Number(item.radiationRemove));
    }
}

function raidSession(playerId,token){
    return db.prepare('SELECT * FROM raid_sessions WHERE player_id=? AND token=?').get(playerId,token);
}

function raidClearPending(playerId){
    db.prepare('UPDATE raid_sessions SET pending_type=NULL,pending_payload=NULL,updated_at=? WHERE player_id=?')
      .run(Date.now(),playerId);
}

function serverArtifactDef(name){
    if(!name) return null;
    const exact=String(name);
    const crafted=db.prepare('SELECT name,tier,price,stats,gen FROM crafted_artifacts WHERE name=?').get(exact);
    if(crafted){
        let stats={}; try{stats=JSON.parse(crafted.stats||'{}')}catch(_){}
        return {name:crafted.name,tier:Number(crafted.tier)||1,stats,gen:Number(crafted.gen)||0,crafted:true};
    }
    const clean=String(exact).replace(/[\u200B\u200C]+$/,'');
    const base=SHOP_ARTIFACTS.find(a=>a.name===clean);
    if(base) return {...base};
    const named=db.prepare('SELECT artifact_name,stats FROM named_artifacts WHERE artifact_name=?').get(clean);
    if(named){
        let stats={}; try{stats=JSON.parse(named.stats||'{}')}catch(_){}
        return {name:named.artifact_name,tier:9,stats,isNamedArtifact:true};
    }
    return null;
}

function serverRecomputeArtifactDerived(playerId,data){
    data.radiationResist=0;
    data.radiationLeakTotal=0;
    data.anomalyResist={};
    data.namedArtifactBonus={vitality:0,agility:0,strength:0,accuracy:0,intellect:0,luck:0,bulletResist:0,hitAbsorption:0};
    const perkKeys=new Set(['vitality','agility','strength','accuracy','intellect','luck']);
    const add=(stats)=>{
        if(!stats||typeof stats!=='object') return;
        for(const [stat,raw] of Object.entries(stats)){
            const v=Number(raw)||0;
            if(stat==='radiation') data.radiationResist+=v;
            else if(stat==='radiationLeak') data.radiationLeakTotal+=-v;
            else if(stat.startsWith('anomaly_')){
                const n=stat.slice('anomaly_'.length);
                data.anomalyResist[n]=(Number(data.anomalyResist[n])||0)+v;
            }else if(perkKeys.has(stat)||stat==='bulletResist'||stat==='hitAbsorption'){
                data.namedArtifactBonus[stat]=(Number(data.namedArtifactBonus[stat])||0)+v;
            }
        }
    };
    for(const name of (Array.isArray(data.artifactSlots)?data.artifactSlots:[])){
        const a=serverArtifactDef(name); if(a) add(a.stats);
    }
    const cap=150;
    data.namedArtifactBonus.bulletResist=Math.max(-cap,Math.min(cap,Number(data.namedArtifactBonus.bulletResist)||0));
    data.namedArtifactBonus.hitAbsorption=Math.max(-cap,Math.min(cap,Number(data.namedArtifactBonus.hitAbsorption)||0));
    if(data.armor&&data.armor.name){
        const eff=getArmorEffectiveStatsServer(data.armor.name,data);
        if(eff) add(eff.stats);
    }
    const eco=pveFactionBonuses(playerId,data,null).anomalyRadResistPct;
    if(eco){
        data.radiationResist=Math.round(data.radiationResist*(1+eco/100)*10)/10;
        for(const n of Object.keys(data.anomalyResist))
            data.anomalyResist[n]=Math.round(data.anomalyResist[n]*(1+eco/100)*10)/10;
    }
}

function parseGearNameServer(name) {
    const clean = String(name || '').replace(/[\u200B\u200C]+$/, '');
    const m = clean.match(/^(.*) \+(\d+)$/);
    if (m) return { baseName: m[1], level: parseInt(m[2], 10) };
    return { baseName: clean, level: 0 };
}

function getStableArmorKeyServer(name) {
    const invisibleMatch = String(name).match(/[\u200B\u200C]+$/);
    const visiblePart = String(name).replace(/[\u200B\u200C]+$/, '');
    const withoutLevel = visiblePart.replace(/ \+\d+$/, '');
    return withoutLevel + (invisibleMatch ? invisibleMatch[0] : '');
}

function getArmorEffectiveStatsServer(itemName, data) {
    const parsed = parseGearNameServer(itemName);
    const base = SHOP_ARMOR.find(a => a.name === parsed.baseName);
    if (!base) return null;
    const stableKey = getStableArmorKeyServer(itemName);
    const u = (data.armorUpgradeData && data.armorUpgradeData[stableKey]) || {};
    const bulletResist = getUpgradedStatServer(base.armor, u.armor || 0, getNextItemCeilingServer(SHOP_ARMOR, base, 'armor'), !!base.adminOnly);
    const hitAbsorption = getUpgradedStatServer(base.hitAbsorption || 0, u.hitAbsorption || 0, getNextItemCeilingServer(SHOP_ARMOR, base, 'hitAbsorption'), !!base.adminOnly);
    const stats = { ...(base.stats || {}) };
    Object.keys(u).forEach(key => {
        if (key === 'armor' || key === 'hitAbsorption') return;
        stats[key] = getUpgradedStatServer(stats[key] || 0, u[key], undefined, !!base.adminOnly);
    });
    return { bulletResist, hitAbsorption, stats };
}

function getUpgradedStatServer(baseStat, level, ceiling, adminOnly = false) {
    if (adminOnly) {
        const legacyLevel = Math.max(0, Number(level) || 0);
        const legacyBase = Number(baseStat) || 0;
        const legacyPct = Math.min(0.5, legacyLevel * 0.005);
        return legacyBase === 0 ? Math.round(legacyLevel) : Math.round(legacyBase * (1 + legacyPct));
    }
    const lvl = Math.min(UPGRADE_MAX_LEVEL, Math.max(0, Number(level) || 0));
    const base = Number(baseStat) || 0;
    const pct = Math.min(UPGRADE_MAX_BONUS_PCT_SERVER, lvl * (UPGRADE_MAX_BONUS_PCT_SERVER / UPGRADE_MAX_LEVEL));
    // Новая защита с базой 0 должна реально появляться после первого улучшения.
    const raw = base === 0 ? Math.round(lvl) : Math.round(base * (1 + pct));
    return (typeof ceiling === 'number') ? Math.min(raw, ceiling) : raw;
}

function getNextItemCeilingServer(list, item, statKey) {
    if (!item || item.unlockLevel === undefined) return Infinity;
    const candidates = list.filter(o => !o.adminOnly && !o.isPremiumArmor && !o.isResearchSuit &&
        o.unlockLevel !== undefined && o.unlockLevel > item.unlockLevel);
    if (candidates.length === 0) return Infinity;
    const minUnlock = Math.min(...candidates.map(o => o.unlockLevel));
    const nextTier = candidates.filter(o => o.unlockLevel === minUnlock);
    nextTier.sort((a, b) => (Number(a[statKey]) || 0) - (Number(b[statKey]) || 0));
    const nextItem = nextTier[0];
    const nextCeiling = getNextItemCeilingServer(list, nextItem, statKey);
    const nextValueAt20 = getUpgradedStatServer(Number(nextItem[statKey]) || 0, 20, nextCeiling);
    return Math.max((Number(item[statKey]) || 0), nextValueAt20);
}
